// Score results: compare the agent's tier with the expected tier
const leads = $('Load test leads').all().map((i) => i.json);
const results = $input.all();

// Match each result to its lead by email (the loop sends leads one at a time)
const norm = (e) => (e || '').toString().trim().toLowerCase();
const byEmail = {};
for (const r of results) byEmail[norm(r.json.email)] = r.json;

// Rule-only baseline: what the rules alone would say (same thresholds as the AI fallback)
const ruleTier = (score) => (score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Cold');

const details = leads.map((lead, i) => {
  const r = byEmail[norm(lead['Work email'])] || { error: 'no result for this lead' };
  let actual;
  if (r.error) actual = 'error';
  else if (r.valid === false) actual = 'Rejected';
  else actual = r.tier || 'missing';

  let ruleOnly;
  if (r.valid === false) ruleOnly = 'Rejected';
  else if (typeof r.ruleScore === 'number') ruleOnly = ruleTier(r.ruleScore);
  else ruleOnly = 'missing';

  return {
    id: lead.id,
    name: lead['Name'],
    case: lead.case,
    expected: lead.expectedTier,
    actual,
    correct: actual === lead.expectedTier,
    ruleOnly,
    ruleOnlyCorrect: ruleOnly === lead.expectedTier,
    ruleScore: r.ruleScore ?? null,
    fitScore: r.fitScore ?? null,
    aiStatus: r.valid === false ? 'skipped' : (r.aiStatus || ''),
    guardFlags: (r.guardFlags || []).join('; '),
    latencyMs: r.valid === false ? null : (r.latencyMs ?? null),
    error: r.error || '',
  };
});

const total = details.length;
const correct = details.filter((d) => d.correct).length;
const ruleOnlyCorrect = details.filter((d) => d.ruleOnlyCorrect).length;
const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);

// Accuracy per expected tier
const perTier = {};
for (const t of ['Hot', 'Warm', 'Cold', 'Rejected']) {
  const rows = details.filter((d) => d.expected === t);
  perTier[t] = rows.filter((d) => d.correct).length + ' of ' + rows.length;
}

// Latency, only for leads that went through the AI
const lat = details.map((d) => d.latencyMs).filter((v) => typeof v === 'number').sort((a, b) => a - b);
const avgLatencyMs = lat.length ? Math.round(lat.reduce((a, b) => a + b, 0) / lat.length) : null;
const medianLatencyMs = lat.length ? lat[Math.floor(lat.length / 2)] : null;
const maxLatencyMs = lat.length ? lat[lat.length - 1] : null;

// Markdown table to paste into the README
const table = [
  '| # | Case | Expected | Agent | Rules only | OK |',
  '|---|---|---|---|---|---|',
  ...details.map((d) => `| ${d.id} | ${d.case} | ${d.expected} | ${d.actual} | ${d.ruleOnly} | ${d.correct ? 'yes' : 'no'} |`),
].join('\n');

return [{
  json: {
    runAt: new Date().toISOString(),
    total,
    correct,
    accuracyPercent: pct(correct, total),
    ruleOnlyCorrect,
    ruleOnlyAccuracyPercent: pct(ruleOnlyCorrect, total),
    perTier,
    aiFailures: details.filter((d) => d.aiStatus === 'failed').length,
    errors: details.filter((d) => d.actual === 'error').length,
    guardrailDowngrades: details.filter((d) => d.guardFlags).length,
    avgLatencyMs,
    medianLatencyMs,
    maxLatencyMs,
    wrong: details.filter((d) => !d.correct).map((d) => `#${d.id} ${d.case}: expected ${d.expected}, got ${d.actual}`),
    resultsTable: table,
    details,
  },
}];
